package br.com.fiap.resource;
import br.com.fiap.dao.VoucherDAO; import br.com.fiap.entities.Voucher; import br.com.fiap.bo.ValidacaoBO; import br.com.fiap.dao.UsuarioDAO; import br.com.fiap.dao.HistoricoDAO; import br.com.fiap.entities.Usuario; import br.com.fiap.entities.Historico; import java.time.LocalDate;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/vouchers")
public class VoucherResource {
 private final ValidacaoBO validacao; public VoucherResource(ValidacaoBO validacao){this.validacao=validacao;}
 @GetMapping public ResponseEntity<?> listar(){try{return ResponseEntity.ok(new VoucherDAO().listar());}catch(Exception e){return erro();}}
 @GetMapping("/{codigo}") public ResponseEntity<?> buscar(@PathVariable String codigo){try{return new VoucherDAO().listar().stream().filter(v->v.getCodigo().equalsIgnoreCase(codigo)).findFirst().<ResponseEntity<?>>map(ResponseEntity::ok).orElseGet(()->ResponseEntity.notFound().build());}catch(Exception e){return erro();}}
 @PostMapping public ResponseEntity<?> criar(@RequestBody Voucher v){try{validacao.validarVoucher(v);if(v.getCodigo()==null||v.getCodigo().isBlank())v.setCodigo("SOULUP"+(1000+new Random().nextInt(9000)));new VoucherDAO().inserir(v);return ResponseEntity.status(201).body(v);}catch(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("erro",e.getMessage()));}catch(Exception e){return erro();}}
 @PostMapping("/{codigo}/resgates") public ResponseEntity<?> resgatar(@PathVariable String codigo,@RequestParam String email){try{Voucher v=new VoucherDAO().listar().stream().filter(x->x.getCodigo().equalsIgnoreCase(codigo)).findFirst().orElse(null);if(v==null)return ResponseEntity.notFound().build();Usuario u=new UsuarioDAO().listar().stream().filter(x->x.getEmail().equalsIgnoreCase(email)).findFirst().orElse(null);if(u==null)return ResponseEntity.status(404).body(Map.of("erro","Usuário não encontrado."));if(u.getPontos()<v.getPontos())return ResponseEntity.status(409).body(Map.of("erro","Pontos insuficientes para resgatar este voucher."));u.removerPontos(v.getPontos());new UsuarioDAO().atualizar(u);Historico h=new Historico(v.getCodigo(),v.getPontos(),LocalDate.now().toString());new HistoricoDAO().inserir(h,email);return ResponseEntity.ok(Map.of("mensagem","Voucher resgatado com sucesso.","voucher",v,"pontosRestantes",u.getPontos()));}catch(Exception e){e.printStackTrace();return erro();}}
 @PutMapping("/{codigo}") public ResponseEntity<?> atualizar(@PathVariable String codigo,@RequestBody Voucher v){try{if(!existe(codigo))return ResponseEntity.notFound().build();v.setCodigo(codigo);validacao.validarVoucher(v);new VoucherDAO().atualizar(v);return ResponseEntity.ok(v);}catch(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("erro",e.getMessage()));}catch(Exception e){return erro();}}
 @DeleteMapping("/{codigo}") public ResponseEntity<?> excluir(@PathVariable String codigo){try{if(!existe(codigo))return ResponseEntity.notFound().build();new VoucherDAO().deletar(codigo);return ResponseEntity.noContent().build();}catch(Exception e){return erro();}}
 private boolean existe(String c)throws Exception{return new VoucherDAO().listar().stream().anyMatch(v->v.getCodigo().equalsIgnoreCase(c));} private ResponseEntity<?> erro(){return ResponseEntity.status(500).body(Map.of("erro","Não foi possível processar a solicitação."));}
}
